const { createCanvas } = require('canvas');
const fs = require('fs');
const { DOMParser } = require('node:canvas');
const { registerFont } = require('canvas');

// We need to get the SVG from the infographic and render it
// Since we can't run a full browser, we'll create the poster using canvas directly

const width = 600;
const height = 900;
const canvas = createCanvas(width, height);
const ctx = canvas.getContext('2d');

// Background gradient - deep navy
const gradient = ctx.createLinearGradient(0, 0, 0, height);
gradient.addColorStop(0, '#0a0f1e');
gradient.addColorStop(0.5, '#0d1526');
gradient.addColorStop(1, '#0a0f1e');
ctx.fillStyle = gradient;
ctx.fillRect(0, 0, width, height);

// Samsung blue accent
const samsungBlue = '#1428a0';
const lightBlue = '#8ab4f8';
const gold = '#f5c518';
const teal = '#00d4aa';
const white = '#ffffff';
const lightGray = 'rgba(255,255,255,0.6)';

// Header
ctx.fillStyle = samsungBlue;
ctx.fillRect(0, 0, width, 100);

ctx.fillStyle = white;
ctx.font = 'bold 32px sans-serif';
ctx.textAlign = 'center';
ctx.fillText('Samsung Galaxy Ecosystem', width/2, 45);

ctx.fillStyle = lightBlue;
ctx.font = '14px sans-serif';
ctx.letterSpacing = '2px';
ctx.fillText('2025 COLLECTION', width/2, 70);

// Hero section
const heroY = 120;
ctx.fillStyle = white;
ctx.font = 'bold 18px sans-serif';
ctx.textAlign = 'left';

// Hero card 1 - Galaxy S26 Ultra
ctx.fillStyle = samsungBlue;
roundRect(ctx, 20, heroY, (width-40)/2 - 5, 140, 16);
ctx.fill();

ctx.fillStyle = gold;
ctx.fillRect(20, heroY, (width-40)/2 - 5, 4);

ctx.fillStyle = teal;
ctx.beginPath();
ctx.arc((width-40)/2 + 10, heroY + 20, 20, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = white;
ctx.font = 'bold 14px sans-serif';
ctx.textAlign = 'center';
ctx.fillText('NEW', (width-40)/2 + 10, heroY + 25);

ctx.fillStyle = white;
ctx.font = 'bold 16px sans-serif';
ctx.textAlign = 'center';
ctx.fillText('Galaxy S26 Ultra', width/4, heroY + 60);

ctx.fillStyle = lightGray;
ctx.font = '11px sans-serif';
ctx.fillText('Most advanced smartphone', width/4, heroY + 82);
ctx.fillText('with integrated S Pen', width/4, heroY + 96);

ctx.fillStyle = teal;
ctx.font = '10px sans-serif';
ctx.fillText('Galaxy AI', width/4, heroY + 120);

// Hero card 2 - Galaxy Buds4 Pro
ctx.fillStyle = samsungBlue;
roundRect(ctx, (width-40)/2 + 10, heroY, (width-40)/2 - 5, 140, 16);
ctx.fill();

ctx.fillStyle = teal;
ctx.fillRect((width-40)/2 + 10, heroY, (width-40)/2 - 5, 4);

ctx.fillStyle = teal;
ctx.beginPath();
ctx.arc(width - 30, heroY + 20, 20, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = white;
ctx.font = 'bold 14px sans-serif';
ctx.textAlign = 'center';
ctx.fillText('NEW', width - 30, heroY + 25);

ctx.fillStyle = white;
ctx.font = 'bold 16px sans-serif';
ctx.textAlign = 'center';
ctx.fillText('Galaxy Buds4 Pro', width * 3/4, heroY + 60);

ctx.fillStyle = lightGray;
ctx.font = '11px sans-serif';
ctx.fillText('Next-gen ANC &', width * 3/4, heroY + 82);
ctx.fillText('high-fidelity audio', width * 3/4, heroY + 96);

ctx.fillStyle = teal;
ctx.font = '10px sans-serif';
ctx.fillText('Galaxy AI', width * 3/4, heroY + 120);

// Stats row
const statsY = heroY + 160;
ctx.fillStyle = 'rgba(20, 40, 160, 0.15)';
ctx.fillRect(0, statsY, width, 80);

const stats = [
  { value: '7+', label: 'Categories' },
  { value: '14', label: 'Products' },
  { value: '2', label: 'New Flagships' },
  { value: '4+', label: 'AI Products' }
];
const statWidth = width / 4;
stats.forEach((stat, i) => {
  ctx.fillStyle = gold;
  ctx.font = 'bold 28px sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText(stat.value, i * statWidth + statWidth/2, statsY + 35);
  ctx.fillStyle = lightGray;
  ctx.font = '10px sans-serif';
  ctx.fillText(stat.label, i * statWidth + statWidth/2, statsY + 55);
});

// Section title
const sectionY = statsY + 100;
ctx.fillStyle = lightBlue;
ctx.fillRect(20, sectionY, 4, 20);
ctx.fillStyle = white;
ctx.font = 'bold 16px sans-serif';
ctx.textAlign = 'left';
ctx.fillText('Complete Ecosystem', 35, sectionY + 15);

// Category grid
const catY = sectionY + 40;
const categories = [
  { name: 'Smartphones', product: 'Galaxy S26 Ultra', tag: 'NEW', tagColor: teal },
  { name: 'Foldables', product: 'Galaxy Z Fold7, Z Flip7', tag: 'Galaxy AI', tagColor: lightBlue },
  { name: 'Tablets', product: 'Galaxy Tab S11 Series', tag: null },
  { name: 'Wearables', product: 'Galaxy Watch Ultra', tag: null },
  { name: 'Audio', product: 'Galaxy Buds4 Pro', tag: 'NEW', tagColor: teal },
  { name: 'Television', product: 'Neo QLED 8K, The Frame', tag: null },
  { name: 'Home Appliances', product: 'Bespoke AI Refrigerator', tag: 'Bespoke AI', tagColor: gold },
  { name: 'Climate', product: 'Air Conditioners', tag: null }
];

categories.forEach((cat, i) => {
  const col = i % 2;
  const row = Math.floor(i / 2);
  const x = 20 + col * ((width - 40) / 2 + 5);
  const y = catY + row * 75;

  ctx.fillStyle = 'rgba(20, 40, 160, 0.15)';
  roundRect(ctx, x, y, (width - 50) / 2, 65, 12);
  ctx.fill();

  ctx.fillStyle = lightBlue;
  ctx.font = '10px sans-serif';
  ctx.textAlign = 'left';
  ctx.fillText(cat.name.toUpperCase(), x + 14, y + 20);

  ctx.fillStyle = white;
  ctx.font = 'bold 13px sans-serif';
  ctx.fillText(cat.product, x + 14, y + 40);

  if (cat.tag) {
    ctx.fillStyle = cat.tagColor === gold ? 'rgba(245, 197, 24, 0.2)' : cat.tagColor === teal ? 'rgba(0, 212, 170, 0.2)' : 'rgba(138, 180, 248, 0.2)';
    ctx.fillRect(x + 14, y + 48, 70, 14);
    ctx.fillStyle = cat.tagColor;
    ctx.font = '9px sans-serif';
    ctx.fillText(cat.tag, x + 22, y + 58);
  }
});

// AI section
const aiY = catY + 165;
ctx.fillStyle = lightBlue;
ctx.fillRect(20, aiY, 4, 20);
ctx.fillStyle = white;
ctx.font = 'bold 16px sans-serif';
ctx.fillText('AI-Powered Innovation', 35, aiY + 15);

// AI cards
const aiCardY = aiY + 40;
ctx.fillStyle = 'rgba(20, 40, 160, 0.3)';
roundRect(ctx, 20, aiCardY, (width-50)/2, 90, 12);
ctx.fill();
ctx.fillStyle = gold;
ctx.fillRect(width/2 - 45, aiCardY + 15, 40, 3);
ctx.fillStyle = white;
ctx.font = 'bold 16px sans-serif';
ctx.textAlign = 'center';
ctx.fillText('Bespoke AI', width/4, aiCardY + 40);
ctx.fillStyle = lightGray;
