const Jimp = require('jimp');

const width = 600;
const height = 900;

// Color definitions
const colors = {
  deepNavy: 0x0a0f1e,
  darkBlue: 0x0d1526,
  samsungBlue: 0x1428a0,
  lightBlue: 0x8ab4f8,
  gold: 0xf5c518,
  teal: 0x00d4aa,
  white: 0xffffff,
  lightGray: 0x999999,
  cardBg: 0x1a2540
};

async function createPoster() {
  // Create new image with background
  const image = new Jimp(width, height, colors.deepNavy);

  // Helper to draw rounded rectangle (simplified - just filled rect for now)
  const drawRect = async (x, y, w, h, color) => {
    for (let py = y; py < y + h; py++) {
      for (let px = x; px < x + w; px++) {
        if (px >= 0 && px < width && py >= 0 && py < height) {
          image.setPixelColor(color, px, py);
        }
      }
    }
  };

  // Helper to blend color onto existing
  const blendRect = (x, y, w, h, color, alpha = 1) => {
    for (let py = y; py < y + h && py < height; py++) {
      for (let px = x; px < x + w && px < width; px++) {
        if (py >= 0 && px >= 0) {
          const existing = image.getPixelColor(px, py);
          const blended = blendColors(existing, color, alpha);
          image.setPixelColor(blended, px, py);
        }
      }
    }
  };

  // Blend two colors with alpha
  const blendColors = (c1, c2, alpha) => {
    const r1 = (c1 >> 24) & 0xff, g1 = (c1 >> 16) & 0xff, b1 = (c1 >> 8) & 0xff, a1 = c1 & 0xff;
    const r2 = (c2 >> 24) & 0xff, g2 = (c2 >> 16) & 0xff, b2 = (c2 >> 8) & 0xff, a2 = c2 & 0xff;
    const r = Math.round(r1 * (1 - alpha) + r2 * alpha);
    const g = Math.round(g1 * (1 - alpha) + g2 * alpha);
    const b = Math.round(b1 * (1 - alpha) + b2 * alpha);
    return (r << 24) | (g << 16) | (b << 8) | 0xff;
  };

  // Draw gradient background
  for (let y = 0; y < height; y++) {
    const ratio = y / height;
    const r = Math.round(0x0a * (1 - ratio) + 0x0d * ratio);
    const g = Math.round(0x0f * (1 - ratio) + 0x15 * ratio);
    const b = Math.round(0x1e * (1 - ratio) + 0x26 * ratio);
    const color = (r << 24) | (g << 16) | (b << 8) | 0xff;
    for (let x = 0; x < width; x++) {
      image.setPixelColor(color, x, y);
    }
  }

  // Header background
  blendRect(0, 0, width, 100, colors.samsungBlue);

  // Draw text - we need to load a font
  const fontBig = await Jimp.loadFont(Jimp.FONT_SANS_32_BLACK);
  const fontMedium = await Jimp.loadFont(Jimp.FONT_SANS_16_BLACK);
  const fontSmall = await Jimp.loadFont(Jimp.FONT_SANS_12_BLACK);

  // Title
  image.print(fontBig, 0, 30, {
    text: 'Samsung Galaxy Ecosystem',
    alignmentX: Jimp.HORIZONTAL_ALIGN_CENTER,
    alignmentY: Jimp.VERTICAL_ALIGN_TOP
  }, width, 50);

  // Subtitle
  image.print(fontSmall, 0, 65, {
    text: '2025 COLLECTION',
    alignmentX: Jimp.HORIZONTAL_ALIGN_CENTER,
    alignmentY: Jimp.VERTICAL_ALIGN_TOP
  }, width, 30);

  // Hero section - Two cards side by side
  const heroY = 120;
  const cardW = 275;
  const cardH = 130;

  // Card 1 - Galaxy S26 Ultra
  blendRect(20, heroY, cardW, cardH, colors.samsungBlue);
  blendRect(20, heroY, cardW, 4, colors.gold);  // Gold accent on top

  // NEW badge
  blendRect(250, heroY + 12, 45, 20, colors.teal);

  // Card 2 - Galaxy Buds4 Pro
  blendRect(305, heroY, cardW, cardH, colors.samsungBlue);
  blendRect(305, heroY, cardW, 4, colors.teal);  // Teal accent on top

  // NEW badge
  blendRect(535, heroY + 12, 45, 20, colors.teal);

  // Hero card titles and descriptions
  // Since Jimp text rendering is limited, we'll add simple labels
  // Instead, let's use a simpler approach with just key elements

  // Stats row
  const statsY = heroY + 150;
  blendRect(0, statsY, width, 80, 0x1a2840);

  const stats = [
    { value: '7+', label: 'Categories' },
    { value: '14', label: 'Products' },
    { value: '2', label: 'New Flagships' },
    { value: '4+', label: 'AI Products' }
  ];

  // Section title
  const sectionY = statsY + 100;
  blendRect(20, sectionY, 4, 20, colors.samsungBlue);

  // Category grid - 2x4
  const catY = sectionY + 40;
  const categories = [
    { name: 'Smartphones', product: 'Galaxy S26 Ultra', tag: 'NEW', tagColor: colors.teal },
    { name: 'Foldables', product: 'Galaxy Z Fold7, Z Flip7', tag: 'Galaxy AI', tagColor: colors.lightBlue },
    { name: 'Tablets', product: 'Galaxy Tab S11 Series', tag: null },
    { name: 'Wearables', product: 'Galaxy Watch Ultra', tag: null },
    { name: 'Audio', product: 'Galaxy Buds4 Pro', tag: 'NEW', tagColor: colors.teal },
    { name: 'Television', product: 'Neo QLED 8K, The Frame', tag: null },
    { name: 'Home Appliances', product: 'Bespoke AI Refrigerator', tag: 'Bespoke AI', tagColor: colors.gold },
    { name: 'Climate', product: 'Air Conditioners', tag: null }
  ];

  const cardWidth = 270;
  const cardHeight = 65;
  const gap = 10;

  categories.forEach((cat, i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const x = 20 + col * (cardWidth + gap);
    const y = catY + row * (cardHeight + gap);

    blendRect(x, y, cardWidth, cardHeight, colors.cardBg);
  });

  // AI section
  const aiY = catY + 165;
  blendRect(20, aiY, 4, 20, colors.samsungBlue);

  // AI cards
  const aiCardY = aiY + 40;
  blendRect(20, aiCardY, 270, 90, 0x2a3860);
  blendRect(305, aiCardY, 270, 90, 0x2a3860);

  // Footer line
  blendRect(0, aiCardY + 110, width, 1, 0x3a4870);

  // Save the image
  await image.writeAsync('/app/output/final_poster.png');
  console.log('Poster saved to /app/output/final_poster.png');
}

